output_text:
[
  {
    "id": "take_entrance_cart",
    "text": "A shopper must collect the available shopping cart from the entrance cart station before continuing the trip.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "with_cart": "hasCart"
      },
      "events": {
        "pickup_entrance_cart": {
          "pre": {
            "and": [
              "at_entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "with_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entrance_cart"
    }
  },
  {
    "id": "no_items_without_cart",
    "text": "A shopper may not pick up required items unless they are currently using a shopping cart.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper should not carry goods by hand; items should be transported in the cart instead.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "properly_using_cart": {
          "and": [
            "hasCart",
            {
              "not": "handFull"
            }
          ]
        }
      },
      "events": {
        "becomes_hand_full": {
          "pre": {
            "not": "handFull"
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_cart_to_counter",
    "text": "After taking a cart, the shopper must return it to the designated counter at cell (0,1) before the trip ends.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "cart_at_counter": "cartAt(0,1)",
        "at_counter": "at(0,1)"
      },
      "events": {
        "cart_taken": {
          "pre": "PICKUP_CART",
          "post": "with_cart"
        },
        "cart_returned_to_counter": {
          "pre": {
            "and": [
              "with_cart",
              "at_counter",
              "LEAVE_CART"
            ]
          },
          "post": "cart_at_counter"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "cart_returned_to_counter"
    }
  },
  {
    "id": "do_not_abandon_cart_elsewhere",
    "text": "A cart may only be left at the designated counter cell (0,1), not at arbitrary store locations.",
    "abstraction": {
      "state_properties": {
        "at_counter": "at(0,1)",
        "away_from_counter": {
          "not": "at(0,1)"
        }
      },
      "events": {
        "leave_cart_away_from_counter": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "away_from_counter"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_away_from_counter"
    }
  },
  {
    "id": "exit_only_after_cart_parked",
    "text": "A shopper may exit only after the cart has been parked at the counter and the shopper is no longer pushing it.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_counter": "cartAt(0,1)",
        "still_with_cart": "hasCart",
        "ready_to_exit": {
          "and": [
            "cart_parked_at_counter",
            {
              "not": "still_with_cart"
            }
          ]
        },
        "not_ready_to_exit": {
          "not": "ready_to_exit"
        }
      },
      "events": {
        "improper_exit": {
          "pre": {
            "and": [
              "EXIT",
              "not_ready_to_exit"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "improper_exit"
    }
  },
  {
    "id": "no_post_return_interactions",
    "text": "Once the cart is parked at the counter, the shopper should not perform further store interactions before exiting.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_counter": "cartAt(0,1)",
        "cartless_after_return": {
          "and": [
            "cart_parked_at_counter",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "cartless_after_return",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  },
  {
    "id": "cart_restricted_lower_right_aisle",
    "text": "Shopping carts are not allowed in the narrow lower-right aisle cells around (7,4) and (8,4).",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "narrow_lower_right_aisle": {
          "or": [
            "at(7,4)",
            "at(8,4)"
          ]
        },
        "cart_in_narrow_aisle": {
          "and": [
            "with_cart",
            "narrow_lower_right_aisle"
          ]
        }
      },
      "events": {
        "enter_narrow_aisle_with_cart": {
          "pre": {
            "and": [
              "with_cart",
              "MOVE"
            ]
          },
          "post": "narrow_lower_right_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_narrow_aisle"
    }
  }
]
